import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type BatteryWasteAnimationProps = Record<string, any>;

const BatteryWasteAnimation: React.FC<BatteryWasteAnimationProps> = ({
  backgroundColor = "#0B0E14",
  transparentBackground = false,
  durationInSeconds = 6, // Ignored in visual logic, but required by schema
  titleText = "DON'T WASTE",
  highlightText = "YOUR ENERGY",
  batteryCount = 25, // Increased to throw more energy into the bin
  energyColor = "#00FFAA",
  binColor = "#3A4556",
}) => {
  const frame = useCurrentFrame();
  const { width, height, durationInFrames } = useVideoConfig();
  const s = Math.min(width, height);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout parameters
  const binX = width * 0.75;
  const binY = height * 0.65;
  const throwDuration = 45;
  const startFrameOffset = 20;

  // Dynamically calculate stagger so all batteries cleanly land before the video ends
  const availableFrames = durationInFrames - startFrameOffset - throwDuration - 10;
  const stagger = Math.max(1, availableFrames / Math.max(1, batteryCount - 1));

  // Calculate dynamic bin jiggle and total energy accumulation
  let binScaleModifier = 0;
  let totalBinFill = 0;

  for (let i = 0; i < batteryCount; i++) {
    const landFrame = startFrameOffset + i * stagger + throwDuration;
    const impactTime = frame - landFrame;
    
    // Jiggle effect on impact
    if (impactTime > -15 && impactTime < 15) {
      binScaleModifier -= Math.sin(((impactTime + 15) / 30) * Math.PI) * 0.03;
    }

    // Energy accumulation calculation (smooth fill as battery lands)
    const fillContribution = interpolate(
      frame,
      [landFrame - 10, landFrame + 5],
      [0, 1 / batteryCount],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
    totalBinFill += fillContribution;
  }

  // Bin slightly swells as it gets completely full
  const binScale = (s / 1080) * (1 + binScaleModifier + totalBinFill * 0.05);

  // Text Animations
  const textOpacity = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const textY = interpolate(frame, [10, 30], [50, 0], {
    easing: Easing.out(Easing.cubic),
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const liquidY = 280 - (totalBinFill * 260);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      
      {/* Text Content */}
      <div
        style={{
          position: "absolute",
          left: width * 0.1,
          top: height * 0.4,
          transform: `translateY(${textY}px)`,
          opacity: textOpacity,
          display: "flex",
          flexDirection: "column",
          gap: "10px",
        }}
      >
        <h2 style={{ margin: 0, fontSize: s * 0.05, fontWeight: 600, color: "#8B95A5", letterSpacing: "4px" }}>
          {titleText}
        </h2>
        <h1
          style={{
            margin: 0,
            fontSize: s * 0.09,
            fontWeight: 900,
            color: energyColor,
            textShadow: `0 0 60px ${energyColor}AA`,
            lineHeight: 1,
            letterSpacing: "-1px",
          }}
        >
          {highlightText}
        </h1>
      </div>

      {/* Ambient Energy Glow Behind Bin */}
      <div
        style={{
          position: "absolute",
          left: binX,
          top: binY,
          transform: `translate(-50%, -50%)`,
          width: 100,
          height: 100,
          borderRadius: "50%",
          boxShadow: `0 0 200px 100px ${energyColor}`,
          opacity: totalBinFill * 0.6,
          pointerEvents: "none",
        }}
      />

      {/* Bin Back Rim (Rendered Behind Batteries) */}
      <div
        style={{
          position: "absolute",
          left: binX,
          top: binY,
          transform: `translate(-50%, -50%) scale(${binScale})`,
          width: 240,
          height: 300,
          pointerEvents: "none",
        }}
      >
        <svg width="240" height="300" viewBox="0 0 240 300">
          <ellipse cx="120" cy="20" rx="100" ry="25" fill="#1A202C" />
        </svg>
      </div>

      {/* Batteries */}
      {Array.from({ length: batteryCount }).map((_, i) => {
        const startFrame = startFrameOffset + i * stagger;
        const p = interpolate(frame - startFrame, [0, throwDuration], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        // Don't render until it's time to fly (performance optimization)
        if (frame < startFrame - 5) return null;

        // Spread them slightly on the X axis, but drop straight down
        const xOffset = (i % 5 - 2) * 15;
        const x = binX + xOffset;
        
        // Start above the screen and accelerate downwards into the bin
        const y = interpolate(p, [0, 1], [-150, binY - 40], {
          easing: Easing.in(Easing.quad),
        });
        
        // Dynamic tumbling rotation
        const rotation = interpolate(p, [0, 1], [0, 360 + (i % 4) * 90]);

        // Energy drains as it flies to the bin
        const fillProgress = interpolate(p, [0.1, 0.9], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const isLanded = p === 1;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: y,
              transform: `translate(-50%, -50%) rotate(${rotation}deg) scale(${s / 1080})`,
              width: 50,
              height: 100,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              opacity: isLanded ? 0 : 1, // Disappear once fully in the bin
            }}
          >
            {/* Battery Nub */}
            <div style={{ width: 16, height: 8, backgroundColor: "#718096", borderRadius: "4px 4px 0 0" }} />
            {/* Battery Body */}
            <div
              style={{
                flex: 1,
                width: "100%",
                border: "4px solid #718096",
                borderRadius: 10,
                position: "relative",
                backgroundColor: "#1A202C",
                overflow: "hidden",
                boxShadow: `0 0 ${fillProgress * 40}px ${energyColor}AA`,
              }}
            >
              {/* Intense Energy Fill inside battery */}
              <div
                style={{
                  position: "absolute",
                  bottom: 2,
                  left: 2,
                  width: "calc(100% - 4px)",
                  height: `calc(${fillProgress * 100}% - 4px)`,
                  backgroundColor: energyColor,
                  boxShadow: `0 0 20px 2px ${energyColor}, 0 0 10px ${energyColor} inset`,
                  borderRadius: 4,
                  transition: "none",
                }}
              />
            </div>
          </div>
        );
      })}

      {/* Bin Front (Rendered Over Batteries) */}
      <div
        style={{
          position: "absolute",
          left: binX,
          top: binY,
          transform: `translate(-50%, -50%) scale(${binScale})`,
          width: 240,
          height: 300,
          pointerEvents: "none",
        }}
      >
        <svg width="240" height="300" viewBox="0 0 240 300">
          <defs>
            <clipPath id="bin-shape">
              <path d="M 20 20 A 100 25 0 0 0 220 20 L 190 280 Q 120 310 50 280 Z" />
            </clipPath>
          </defs>

          {/* Front Body Base */}
          <path d="M 20 20 A 100 25 0 0 0 220 20 L 190 280 Q 120 310 50 280 Z" fill={binColor} />

          {/* Energy Fill Rising Inside Bin */}
          <g clipPath="url(#bin-shape)">
            <rect
              x="0"
              y={liquidY}
              width="240"
              height={310 - liquidY}
              fill={energyColor}
              opacity={0.85}
            />
            {totalBinFill > 0.001 && (
              <>
                <ellipse
                  cx="120"
                  cy={liquidY}
                  rx={interpolate(liquidY, [20, 280], [100, 70])}
                  ry={interpolate(liquidY, [20, 280], [25, 15])}
                  fill={energyColor}
                  opacity={0.95}
                />
                <ellipse
                  cx="120"
                  cy={liquidY}
                  rx={interpolate(liquidY, [20, 280], [100, 70]) * 0.7}
                  ry={interpolate(liquidY, [20, 280], [25, 15]) * 0.7}
                  fill="#FFFFFF"
                  opacity={0.4}
                />
              </>
            )}
          </g>

          {/* Top Front Highlight Rim */}
          <path d="M 20 20 A 100 25 0 0 0 220 20" fill="none" stroke="#718096" strokeWidth="4" />
          {/* Vertical Can Grooves (layered on top to give physical depth over the energy) */}
          <line x1="70" y1="55" x2="85" y2="270" stroke="#1A202C" strokeWidth="6" strokeLinecap="round" opacity={0.6} />
          <line x1="120" y1="60" x2="120" y2="275" stroke="#1A202C" strokeWidth="6" strokeLinecap="round" opacity={0.6} />
          <line x1="170" y1="55" x2="155" y2="270" stroke="#1A202C" strokeWidth="6" strokeLinecap="round" opacity={0.6} />
        </svg>
      </div>

    </AbsoluteFill>
  );
};

export default BatteryWasteAnimation;